package be.winnetrie.mod.simpleserverutilities.jail;import be.winnetrie.mod.simpleserverutilities.SimpleServerUtilities;import be.winnetrie.mod.simpleserverutilities.permission.PermissionKeys;import be.winnetrie.mod.simpleserverutilities.permission.PermissionService;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.InteractionHand;import net.minecraft.world.InteractionResult;import net.neoforged.bus.api.EventPriority;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.neoforge.event.entity.player.PlayerEvent;import net.neoforged.neoforge.event.entity.player.PlayerInteractEvent;public final class JailEvents{private JailEvents(){}@SubscribeEvent(priority=EventPriority.HIGHEST)public static void left(PlayerInteractEvent.LeftClickBlock e){if(e.getAction()!=PlayerInteractEvent.LeftClickBlock.Action.START||!(e.getEntity() instanceof ServerPlayer p)||!canAdmin(p)||!SimpleServerUtilities.JAIL_SETUP_TOOLS.isTool(p,p.getMainHandItem()))return;String d=p.level().dimension().identifier().toString();SimpleServerUtilities.JAIL_SETUP_TOOLS.selection(p).setPoint1(d,e.getPos());p.sendSystemMessage(Component.literal("Jail selection corner 1 set to "+fmt(e.getPos())+"."));e.setCanceled(true);}@SubscribeEvent(priority=EventPriority.HIGHEST)public static void rightBlock(PlayerInteractEvent.RightClickBlock e){if(!(e.getEntity() instanceof ServerPlayer p)||e.getHand()!=InteractionHand.MAIN_HAND||!canAdmin(p)||!SimpleServerUtilities.JAIL_SETUP_TOOLS.isTool(p,p.getMainHandItem()))return;String d=p.level().dimension().identifier().toString();SimpleServerUtilities.JAIL_SETUP_TOOLS.selection(p).setPoint2(d,e.getPos());p.sendSystemMessage(Component.literal("Jail selection corner 2 set to "+fmt(e.getPos())+". Open Jail Administration to apply it."));e.setCanceled(true);e.setCancellationResult(InteractionResult.SUCCESS);}@SubscribeEvent(priority=EventPriority.HIGHEST)public static void rightAir(PlayerInteractEvent.RightClickItem e){if(!(e.getEntity() instanceof ServerPlayer p)||e.getHand()!=InteractionHand.MAIN_HAND||!canAdmin(p)||!SimpleServerUtilities.JAIL_SETUP_TOOLS.isTool(p,p.getMainHandItem()))return;JailService.send(p,"",0L,"",false);e.setCanceled(true);e.setCancellationResult(InteractionResult.SUCCESS);}@SubscribeEvent public static void logout(PlayerEvent.PlayerLoggedOutEvent e){if(e.getEntity() instanceof ServerPlayer p)SimpleServerUtilities.JAIL_SETUP_TOOLS.forget(p.getUUID());}private static boolean canAdmin(ServerPlayer p){return PermissionService.isAdmin(p)&&PermissionService.getBoolean(p,PermissionKeys.JAILS_ADMIN,false);}private static String fmt(net.minecraft.core.BlockPos p){return p.getX()+", "+p.getY()+", "+p.getZ();}}
